-- relational: Zeile in Tabelle
4 | David | Wolf | NULL | aktiv | 2

// Dokument (JSON)
{ "vorname": "David",
  "klasse": "3BHIT",
  "noten": [
    {"fach": "DBI", "note": 5},
    {"fach": "AM",  "note": 4}
  ] }

# Key-Value
session:8f3a  ->  "user=4"

-- PostgreSQL
CREATE USER app_user
  WITH PASSWORD 'Geheim123';
GRANT SELECT, INSERT, UPDATE
  ON noten TO app_user;
REVOKE UPDATE
  ON noten FROM app_user;

-- MySQL / MariaDB: Benutzer
-- gehört zu einem Host
CREATE USER 'app_user'@'localhost'
  IDENTIFIED BY 'Geheim123';
GRANT SELECT
  ON schule.* -- alle Tabellen
  TO 'app_user'@'localhost';
